Bash: GODOT_API=$(find <user>/yudian-game/tools-bin/Godot.app -name "extension_api.json" 2>/dev/null | head -1); echo "api: $GODOT_API"; if [ -n "$GODOT_API" ]; then python3 -c "
import json
api = json.load(open('$GODOT_API'))
for c in api['classes']:
    if c['name'] == 'RenderingServer':
        for m in c['methods']:
            if 'surface_count' in m['name'] or m['name'] in ('mesh_create','mesh_free'):
                print(m['name'])
"; fi

